/* body: html자식 */
body {
  font-family: 'Pretendard', sans-serif;
}
ul, li {
  margin: 0;
  padding: 0;
  list-style: none;
}
h1, h2, h3, h4, h5, h6, p {
  font-size: inherit; font-weight: normal;
  margin: auto;
}
button {
  margin: 0; padding: 0;
  border: 0; background: none;
  color: inherit;
}

/* component */
.con {
  width: 1050px; 
  margin-left: auto;
  margin-right: auto;
  display: flex;
}


.top-banner {
  height: 42px;
  background-color: #5F0080;
  /* 글자 색상 color */
  color: #fff;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 14px;
}
.utility-menu {
  /* 선 */
}
.utility-con {
  height: 35px;
  justify-content: flex-end;
  align-items: center;
}
.con>nav>ul {
  display: flex;
  gap: 12px;
  font-size: 12px;
}
.signup-link {
 color: #5F0080;
}
.m-header-con {
  justify-content: space-between;
  align-items: center;
  padding-top: 12px;
  padding-bottom: 12px;
}
.brand {
  display: flex; gap: 20px;
  align-items: center;
  width: 250px;
}
.brand-tabs {
  display: flex; gap: 22px;
  font-size: 18px;
  color: #B5B5B5;
}
.brand-tab.active {
  color: #5F0080;
  font-weight: 500;
}
.search {
  width: 400px; height: 48px;
  border: 1px solid #5F0080;
  border-radius: 8px;
  padding-left: 20px;
  padding-right: 20px;
  /* 태그 크기안에 padding과 선 크기 포함 */
  box-sizing: border-box;
  display: flex; align-items: center;
  font-size: 16px; color: #999;
}
.actions {
  width: 250px;
  display: flex; gap: 40px;
  justify-content: flex-end;
}
#actions .location,
#actions .favorite,
#actions .shopping {
  font-size: 28px;
  cursor: pointer;
}
/*.location,.favorite,.shopping 
마우스 올리면 아이콘 색삭 변경*/
#actions .location:hover,
#actions .favorite:hover,
#actions .shopping:hover {
  color: #5F0080;
}

.banner {
  background-color: gray;
  height: 370px;
}
.banner img {
  width: 100%; height: 100%;
  object-fit: cover;
}

.products {
  padding-top: 40px;
  padding-bottom: 40px;
}
.products-con {
  flex-direction: column;
}
.products-header {
  text-align: center;
}
.products-title {
  font-size: 28px;
  color: #333; font-weight: 500;
  padding-bottom: 8px;
}
.products-desc {
  font-size: 16px; color: #999;
}
.product-list {
  padding-top: 23px;
  display: flex; gap: 18px;
}
.product-card {
  /* background-color: gray; */
  flex-grow: 1; flex-basis: 0;
}
.product-image {
  border-radius: 4px;
  overflow: hidden;
}
.product-image img {
  width: 100%;
}
.product-add {
  padding-top: 6px; padding-bottom: 8px;
}
.product-add .shopping {
  font-size: 20px;
}
.add-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px; color: #222;
  border: 1px solid #DFE4EB;
  height: 36px; width: 100%;
  border-radius: 4px;
}
.product-name {
  font-size: 16px; color: #333;
}
.product-original-price {
  font-size: 16px; color: #BCC4CC;
  padding-top: 8px;
  padding-bottom: 7px;
}
.product-discount {
  font-size: 16px; color: #FA622F;
  font-weight: 700;
  padding-right: 8px;
}
.product-price {
  font-size: 16px; color: #222;
  font-weight: 700;
}

.flex-box {
  display: flex;
  flex-direction: row;
}

.row01 {
  /* 배경색 */
  background-color: red;
  /* 높이 */
  height: 100px;
  /* 너비 */
  width: 300px;
}

